process.env.STAFF_PASSWORD = 'pw';
const { app } = require('./src/server');
const server = app.listen(0, async () => {
  const port = server.address().port;
  const base = "'`http://127.0.0.1:${port}`;
  const signIn = await fetch(base + '"'/api/session', {
    method: 'POST', headers: {'content-type':'application/json'},
    body: JSON.stringify({staffId:'ward-a-1', password:'pw'})
  });
  const cookie = signIn.headers.get('set-cookie');
  const withCookie = await fetch(base + '/api/notes', {headers:{cookie: cookie.split(';')[0]}});
  const withoutCookie = await fetch(base + '/api/notes');
  console.log(JSON.stringify({signIn: signIn.status, cookie, withCookie: withCookie.status, withoutCookie: withoutCookie.status}));
  server.close();
});
NODE"

